"use client";

import { useRef } from "react";
import { IconArrowLeft, IconArrowRight } from "@tabler/icons-react";
import { ChromaticImage } from "@/components/ui/chromatic-image";

const projects = [
  {
    title: "Pacific Tides",
    type: "Editorial",
    location: "Oahu, US",
    image:
      "https://images.unsplash.com/photo-1505142468610-359e7d316be0?q=80&w=926&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D",
  },
  {
    title: "Altitude Study",
    type: "Landscape",
    location: "Dolomites, IT",
    image: "https://assets.aceternity.com/screenshots/mountains-2.webp",
  },
  {
    title: "Signal No. 02",
    type: "Digital",
    location: "Studio archive",
    image: "https://assets.aceternity.com/screenshots/vertical-bg-2.webp",
  },
  {
    title: "Signal No. 03",
    type: "Digital",
    location: "Studio archive",
    image: "https://assets.aceternity.com/screenshots/vertical-bg-3.webp",
  },
];

export function ChromaticImageCarouselDemo() {
  const trackRef = useRef<HTMLDivElement>(null);

  const move = (direction: number) => {
    const track = trackRef.current;
    if (!track) return;
    track.scrollBy({
      left: direction * track.clientWidth * 0.72,
      behavior: "smooth",
    });
  };

  return (
    <div className="w-full overflow-hidden py-8 pl-6 text-neutral-950 dark:text-neutral-50 sm:py-10 sm:pl-8">
      <div className="flex items-end justify-between gap-6 pr-6 sm:pr-8">
        <div className="flex flex-col gap-2">
          <p className="font-mono text-sm tracking-wide text-neutral-500 dark:text-neutral-400">
            Selected work
          </p>
          <h3 className="text-balance text-3xl font-medium tracking-tight sm:text-4xl">
            Spaces with a slower rhythm
          </h3>
        </div>
        <div className="flex shrink-0 gap-2">
          <button
            type="button"
            aria-label="Show previous projects"
            onClick={() => move(-1)}
            className="relative grid size-10 place-items-center rounded-full ring-1 ring-black/15 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-neutral-950 dark:ring-white/20 dark:focus-visible:outline-white"
          >
            <IconArrowLeft aria-hidden="true" className="size-6 shrink-0 stroke-neutral-950 dark:stroke-white" />
            <span className="absolute top-1/2 left-1/2 size-[max(100%,3rem)] -translate-1/2 pointer-fine:hidden" aria-hidden="true" />
          </button>
          <button
            type="button"
            aria-label="Show next projects"
            onClick={() => move(1)}
            className="relative grid size-10 place-items-center rounded-full bg-neutral-950 ring-1 ring-neutral-950 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-neutral-950 dark:bg-white dark:ring-white dark:focus-visible:outline-white"
          >
            <IconArrowRight aria-hidden="true" className="size-6 shrink-0 stroke-white dark:stroke-neutral-950" />
            <span className="absolute top-1/2 left-1/2 size-[max(100%,3rem)] -translate-1/2 pointer-fine:hidden" aria-hidden="true" />
          </button>
        </div>
      </div>

      <div
        ref={trackRef}
        className="flex snap-x snap-mandatory gap-4 overflow-x-auto pt-8 [scrollbar-width:none] sm:gap-5 [&::-webkit-scrollbar]:hidden"
      >
        {projects.map((project) => (
          <article
            key={project.title}
            className="flex min-w-[82%] snap-start flex-col gap-4 sm:min-w-[56%] lg:min-w-[42%]"
          >
            <ChromaticImage
              src={project.image}
              alt={`${project.title} visual project`}
              backgroundColor="#171717"
              zoom={0.12}
              displacement={0.032}
              chromaticShift={0.008}
              tilt={0.16}
              className="aspect-[4/5] rounded-[min(1vw,12px)] bg-neutral-100 outline-1 -outline-offset-1 outline-black/10 dark:bg-neutral-900 dark:outline-white/10"
            />
            <div className="flex items-start justify-between gap-5">
              <div className="flex min-w-0 flex-col gap-1">
                <h4 className="truncate text-xl font-medium">{project.title}</h4>
                <p className="text-base/7 text-neutral-500 dark:text-neutral-400 sm:text-sm/6">
                  {project.location}
                </p>
              </div>
              <p className="shrink-0 pt-1 font-mono text-sm tracking-wide text-neutral-500 dark:text-neutral-400">
                {project.type}
              </p>
            </div>
          </article>
        ))}
      </div>
    </div>
  );
}

"use client";

import { ChromaticImage } from "@/components/ui/chromatic-image";

const leftFeatures = [
  {
    number: "01",
    title: "Directional color",
    description:
      "The channel split follows pointer movement, so the image responds to intent instead of playing a fixed loop.",
  },
  {
    number: "02",
    title: "Native WebGL",
    description:
      "The shader runs directly on the GPU without a scene library or animation dependency.",
  },
];

const rightFeatures = [
  {
    number: "03",
    title: "Any image source",
    description:
      "Pass a local asset, CDN URL, or CMS image through one small component API.",
  },
  {
    number: "04",
    title: "Responsive by default",
    description:
      "Cover cropping and resize observation keep the treatment stable at every aspect ratio.",
  },
];

function FeatureColumn({
  features,
}: {
  features: typeof leftFeatures;
}) {
  return (
    <dl className="grid h-full grid-rows-2 divide-y divide-black/10 dark:divide-white/10">
      {features.map((feature) => (
        <div
          key={feature.number}
          className="flex min-h-48 flex-col justify-between gap-8 p-6 sm:p-8"
        >
          <dt className="flex items-start justify-between gap-4">
            <span className="text-lg font-medium">{feature.title}</span>
            <span className="font-mono text-sm tracking-wide text-neutral-400 tabular-nums dark:text-neutral-500">
              {feature.number}
            </span>
          </dt>
          <dd className="max-w-[40ch] text-pretty text-base/7 text-neutral-600 dark:text-neutral-400 sm:text-sm/6">
            {feature.description}
          </dd>
        </div>
      ))}
    </dl>
  );
}

export function ChromaticImageBentoFeaturesDemo() {
  return (
    <div className="w-full p-6 sm:p-10">
      <section className="overflow-hidden rounded-[min(1.5vw,18px)] bg-white text-neutral-950 outline-1 -outline-offset-1 outline-black/10 dark:bg-neutral-900 dark:text-neutral-50 dark:outline-white/10">
        <div className="border-b border-black/10 p-6 dark:border-white/10 sm:p-8">
          <p className="font-mono text-sm tracking-wide text-neutral-500 dark:text-neutral-400">
            Built for expressive media
          </p>
          <h3 className="max-w-[18ch] pt-3 text-balance text-3xl font-medium tracking-tight sm:text-4xl">
            One image, four useful capabilities
          </h3>
        </div>
        <div className="grid lg:grid-cols-[3fr_4fr_3fr]">
          <div className="order-2 border-black/10 dark:border-white/10 lg:order-1 lg:border-r">
            <FeatureColumn features={leftFeatures} />
          </div>
          <ChromaticImage
            src="https://assets.aceternity.com/screenshots/green-dither-2.webp"
            alt="Green dithered abstract gradient"
            backgroundColor="#9cae65"
            zoom={0.14}
            displacement={0.035}
            chromaticShift={0.009}
            tilt={0.14}
            className="order-1 aspect-[4/5] min-h-96 bg-stone-300 dark:bg-neutral-800 lg:order-2 lg:aspect-auto lg:min-h-[42rem]"
          />
          <div className="order-3 border-t border-black/10 dark:border-white/10 lg:border-t-0 lg:border-l">
            <FeatureColumn features={rightFeatures} />
          </div>
        </div>
      </section>
    </div>
  );
}
